    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (1, 1, 'ru', 'Пятизвёздочный отель у реки в самом сердце Парижа, в двух шагах от Сены.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (2, 1, 'es', 'Un alojamiento de cinco estrellas junto al río, en el corazón de París, a pasos del Sena.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (3, 1, 'fr', 'Un séjour cinq étoiles au bord de l''eau, en plein cœur de Paris, à deux pas de la Seine.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (4, 1, 'it', 'Un soggiorno a cinque stelle sul fiume, nel cuore di Parigi, a pochi passi dalla Senna.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (5, 1, 'ja', 'パリの中心部、セーヌ川のほとりに佇む五つ星の川辺の宿。');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (6, 2, 'ru', 'Классическая римская элегантность в двух шагах от фонтана Треви.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (7, 2, 'es', 'Elegancia romana clásica a poca distancia a pie de la Fontana di Trevi.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (8, 2, 'fr', 'Une élégance romaine classique à deux pas de la fontaine de Trevi.');
