    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (128, 26, 'fr', 'Un appartement calme dans une mews derrière Queen Square, à quelques pas du British Museum.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (129, 26, 'it', 'Un appartamento tranquillo in una mews dietro Queen Square, a due passi dal British Museum.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (130, 26, 'ja', 'クイーン・スクエア裏の静かなミューズフラット。大英博物館まで徒歩圏内。');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (131, 27, 'ru', 'Довоенные апартаменты с одной спальней на обсаженной деревьями улице Уэст-Виллидж, над угловым книжным магазином.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (132, 27, 'es', 'Un apartamento de un dormitorio de preguerra en una manzana arbolada del West Village, sobre una librería de esquina.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (133, 27, 'fr', 'Un appartement d''une chambre d''avant-guerre dans une rue arborée du West Village, au-dessus d''une librairie de quartier.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (134, 27, 'it', 'Un appartamento con una camera d''anteguerra in un isolato alberato del West Village, sopra una libreria d''angolo.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (135, 27, 'ja', '街路樹の並ぶウエスト・ビレッジの一角、角の書店の上にある戦前建築の1ベッドルーム。');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (136, 28, 'ru', 'Переоборудованный фабричный лофт с видом на панораму Ист-Ривер, в двух кварталах от прибрежного парка.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (137, 28, 'es', 'Un loft industrial reconvertido con vistas al skyline del East River, a dos manzanas del parque frente al río.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (138, 28, 'fr', 'Un loft industriel réaménagé avec vue sur les gratte-ciel de l''East River, à deux blocs du parc en bord de fleuve.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (139, 28, 'it', 'Un loft industriale riconvertito con vista sullo skyline dell''East River, a due isolati dal parco sul fiume.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (140, 28, 'ja', 'イーストリバーの街並みを望む改装工場ロフト。ウォーターフロントパークまで2ブロック。');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (141, 29, 'ru', 'Классическая квартира на шесть комнат с двумя спальнями, окнами во внутренний дворик, в трёх кварталах от Центрального парка.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (142, 29, 'es', 'Un clásico "classic six" de dos dormitorios frente a un patio tranquilo, a tres manzanas de Central Park.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (143, 29, 'fr', 'Un « classic six » de deux chambres donnant sur une cour tranquille, à trois blocs de Central Park.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (144, 29, 'it', 'Un classico "classic six" con due camere affacciato su un cortile tranquillo, a tre isolati da Central Park.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (145, 29, 'ja', '静かな中庭に面したクラシックな2ベッドルーム住居。セントラルパークまで3ブロック。');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (146, 30, 'ru', 'Апартаменты на первом уровне с прямым выходом на мелководье лагуны и собственным причалом.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (147, 30, 'es', 'Un apartamento a nivel del suelo que se abre directamente a las aguas someras de la laguna, con embarcadero privado.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (148, 30, 'fr', 'Un appartement de plain-pied ouvrant directement sur les eaux peu profondes du lagon, avec ponton privé.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (149, 30, 'it', 'Un appartamento al piano terra che si apre direttamente sulle acque basse della laguna, con pontile privato.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (150, 30, 'ja', 'ラグーンの浅瀬に直結する地上階アパートメント。専用桟橋付き。');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (151, 31, 'ru', 'Садовая вилла с двумя спальнями в тени кокосовых пальм, в нескольких минутах ходьбы от домашнего рифа.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (152, 31, 'es', 'Una villa-jardín de dos dormitorios a la sombra de palmeras cocoteras, a pocos pasos del arrecife.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (153, 31, 'fr', 'Une villa-jardin de deux chambres à l''ombre des cocotiers, à quelques pas du récif.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (154, 31, 'it', 'Una villa-giardino con due camere all''ombra di palme da cocco, a pochi passi dalla barriera corallina.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (155, 31, 'ja', 'ヤシの木陰に佇む2ベッドルームのガーデンヴィラ。ハウスリーフまで徒歩すぐ。');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (156, 32, 'ru', 'Квартира с одной спальней и собственной солнечной террасой над мелководьем, добраться можно на катере.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (157, 32, 'es', 'Un piso de un dormitorio con solárium privado sobre aguas someras, accesible en un breve traslado en barco.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (158, 32, 'fr', 'Un appartement d''une chambre avec solarium privé au-dessus des hauts-fonds, accessible par une courte navette en bateau.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (159, 32, 'it', 'Un appartamento con una camera e solarium privato sulle acque basse, raggiungibile con un breve trasferimento in barca.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (160, 32, 'ja', '浅瀬の上に張り出す専用サンデッキ付きの1ベッドルーム。ボートで短時間の移動でアクセス。');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (161, 33, 'ru', 'Апартаменты с одной спальней в тихом дворике Марэ, в пяти минутах от площади Вогезов.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (162, 33, 'es', 'Un apartamento de un dormitorio en un tranquilo patio del Marais, a cinco minutos de la Place des Vosges.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (163, 33, 'fr', 'Un appartement d''une chambre sur une cour tranquille du Marais, à cinq minutes de la place des Vosges.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (164, 33, 'it', 'Un appartamento con una camera su un tranquillo cortile del Marais, a cinque minuti da Place des Vosges.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (165, 33, 'ja', 'マレ地区の静かな中庭にある1ベッドルーム。ヴォージュ広場まで徒歩5分。');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (166, 34, 'ru', 'Лофт на верхнем этаже со студией под мансардным окном, на крутом переулке над Мулен де ла Галетт.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (167, 34, 'es', 'Un loft en el último piso con estudio abuhardillado, en la empinada calle sobre el Moulin de la Galette.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (168, 34, 'fr', 'Un loft au dernier étage avec atelier sous verrière, dans la ruelle pentue au-dessus du Moulin de la Galette.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (169, 34, 'it', 'Un loft all''ultimo piano con studio con lucernario, nella ripida stradina sopra il Moulin de la Galette.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (170, 34, 'ja', 'ムーラン・ド・ラ・ギャレットを見下ろす急な坂道に建つ、天窓アトリエ付き最上階ロフト。');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (171, 35, 'ru', 'Квартира с двумя спальнями с видом на приватный сад во дворе, за углом от Café de Flore.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (172, 35, 'es', 'Un piso de dos dormitorios con vistas a un jardín interior privado, a la vuelta de la esquina del Café de Flore.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (173, 35, 'fr', 'Un appartement de deux chambres donnant sur un jardin intérieur privé, à deux pas du Café de Flore.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (174, 35, 'it', 'Un appartamento con due camere affacciato su un giardino interno privato, dietro l''angolo dal Café de Flore.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (175, 35, 'ja', 'プライベートな中庭庭園を望む2ベッドルーム。カフェ・ド・フロールのすぐ裏手。');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (176, 36, 'ru', 'Апартаменты на первом этаже вокруг общего дворика, увитого плющом, на одной из мощёных улочек Трастевере.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (177, 36, 'es', 'Un apartamento en planta baja alrededor de un patio compartido cubierto de hiedra, en una de las callejuelas empedradas de Trastevere.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (178, 36, 'fr', 'Un appartement de plain-pied autour d''une cour commune couverte de lierre, dans l''une des ruelles pavées de Trastevere.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (179, 36, 'it', 'Un appartamento al piano terra intorno a un cortile comune coperto d''edera, in uno dei vicoli acciottolati di Trastevere.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (180, 36, 'ja', '蔦の絡まる共有中庭を囲む1階アパートメント。トラステヴェレの石畳の路地に佇む。');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (181, 37, 'ru', 'Лофт со сводчатым потолком в старейшем районе Рима, в десяти минутах ходьбы от Колизея.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (182, 37, 'es', 'Un loft de techos abovedados en el rione más antiguo de Roma, a diez minutos a pie del Coliseo.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (183, 37, 'fr', 'Un loft à plafond voûté dans le plus vieux rione de Rome, à dix minutes à pied du Colisée.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (184, 37, 'it', 'Un loft a soffitti a volta nel rione più antico di Roma, a dieci minuti a piedi dal Colosseo.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (185, 37, 'ja', 'ローマ最古の街区にあるヴォールト天井のロフト。コロッセオまで徒歩10分。');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (186, 38, 'ru', 'Квартира с одной спальней над крытым продуктовым рынком Тестаччо, в наименее туристическом районе Рима.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (187, 38, 'es', 'Un piso de un dormitorio sobre el mercado cubierto de Testaccio, en el rione menos turístico de Roma.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (188, 38, 'fr', 'Un appartement d''une chambre au-dessus du marché couvert de Testaccio, dans le rione le moins touristique de Rome.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (189, 38, 'it', 'Un appartamento con una camera sopra il mercato coperto di Testaccio, nel rione meno turistico di Roma.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (190, 38, 'ja', 'テスタッチョの屋根付き市場の上にある1ベッドルーム。ローマで最も観光客の少ない街区。');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (191, 39, 'ru', 'Белоснежная квартира с одной спальней, вырубленная в краю кальдеры, с беспрепятственным видом на закат.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (192, 39, 'es', 'Un apartamento encalado de un dormitorio tallado en el borde de la caldera, con vistas ininterrumpidas a la puesta de sol.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (193, 39, 'fr', 'Un appartement blanchi à la chaux d''une chambre, taillé dans le rebord de la caldeira, avec vue imprenable sur le coucher du soleil.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (194, 39, 'it', 'Un appartamento imbiancato a calce con una camera, scavato nel bordo della caldera, con vista ininterrotta sul tramonto.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (195, 39, 'ja', 'カルデラの縁に彫られた白亜の1ベッドルーム。夕日を遮るもののない絶景。');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (196, 40, 'ru', 'Двухуровневый лофт, встроенный в скалу, в нескольких минутах ходьбы от канатной дороги Фиры.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (197, 40, 'es', 'Un loft de dos niveles construido en el acantilado, a poca distancia a pie de la estación del teleférico de Fira.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (198, 40, 'fr', 'Un loft à deux niveaux construit à même la falaise, à quelques pas de la station du téléphérique de Fira.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (199, 40, 'it', 'Un loft su due livelli costruito nella falesia, a pochi passi dalla stazione della funivia di Fira.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (200, 40, 'ja', '断崖に建つスキップフロアのロフト。フィラのケーブルカー駅まで徒歩すぐ。');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (201, 41, 'ru', 'Квартира из камня в горной деревне Санторини, вдали от толп у кальдеры.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (202, 41, 'es', 'Un piso de piedra en el pueblo de la colina de Santorini, lejos de las multitudes de la caldera.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (203, 41, 'fr', 'Un appartement en pierre dans le village perché de Santorin, loin de la foule de la caldeira.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (204, 41, 'it', 'Un appartamento in pietra nel villaggio collinare di Santorini, lontano dalla folla della caldera.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (205, 41, 'ja', 'カルデラの喧騒を離れた、サントリーニの丘の村にある石造りのフラット。');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (206, 42, 'ru', 'Отреставрированный деревянный дом-тямия в одном из немногих районов Токио, уцелевших во время войны.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (207, 42, 'es', 'Una casa machiya de madera restaurada en uno de los pocos barrios de Tokio que sobrevivieron intactos a la guerra.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (208, 42, 'fr', 'Une maison machiya en bois restaurée dans l''un des rares quartiers de Tokyo à avoir survécu intact à la guerre.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (209, 42, 'it', 'Una casa machiya in legno restaurata in uno dei pochi quartieri di Tokyo sopravvissuti intatti alla guerra.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (210, 42, 'ja', '戦火を免れた東京の数少ない町並みに残る、改装済みの木造町家。');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (211, 43, 'ru', 'Апартаменты с одной спальней на канале реки Мэгуро, под сакурами рядом со станцией.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (212, 43, 'es', 'Un apartamento de un dormitorio junto al canal del río Meguro, bajo los cerezos cerca de la estación.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (213, 43, 'fr', 'Un appartement d''une chambre au bord du canal de la rivière Meguro, sous les cerisiers près de la gare.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (214, 43, 'it', 'Un appartamento con una camera sul canale del fiume Meguro, sotto i ciliegi vicino alla stazione.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (215, 43, 'ja', '目黒川沿いの1ベッドルーム。駅近くの桜並木の下に佇む。');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (216, 44, 'ru', 'Двухуровневый лофт над магазином пластинок, в токийском квартале театров и винтажной одежды.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (217, 44, 'es', 'Un loft de dos niveles sobre una tienda de discos, en el barrio de teatros y ropa vintage de Tokio.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (218, 44, 'fr', 'Un loft à deux niveaux au-dessus d''un disquaire, dans le quartier des théâtres et du vintage de Tokyo.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (219, 44, 'it', 'Un loft su due livelli sopra un negozio di dischi, nel quartiere dei teatri e del vintage di Tokyo.');
    INSERT INTO hotel_translations (id, hotel_id, locale, description) VALUES (220, 44, 'ja', 'レコード店の上にある2階建てロフト。劇場とヴィンテージ古着店が並ぶ下北沢エリア。');
