    INSERT INTO reviews (id, rating, comment, created_at, is_approved, booking_id, user_id, room_id) VALUES (1, 5, 'The room over the courtyard was quiet and spotless, and the front desk held our luggage after checkout without any fuss.', '2026-05-16 09:00:00', true, 1, 1, 1);
    INSERT INTO reviews (id, rating, comment, created_at, is_approved, booking_id, user_id, room_id) VALUES (2, 4, 'Junior suite was bigger than expected and the partial river view was a nice surprise. Breakfast options were a bit repetitive by day three.', '2026-04-06 10:30:00', true, 2, 2, 2);
    INSERT INTO reviews (id, rating, comment, created_at, is_approved, booking_id, user_id, room_id) VALUES (3, 5, 'Booked the suite for a family trip — the private balcony made mornings with coffee genuinely memorable. Would stay again.', '2026-03-21 08:15:00', true, 3, 3, 3);
    INSERT INTO reviews (id, rating, comment, created_at, is_approved, booking_id, user_id, room_id) VALUES (4, 3, 'Room was clean but noise from the street was noticeable at night with the window cracked. Staff were helpful when we asked to switch floors.', '2026-06-04 12:00:00', true, 4, 4, 1);
    INSERT INTO reviews (id, rating, comment, created_at, is_approved, booking_id, user_id, room_id) VALUES (5, 5, 'The deluxe room at the Bloomsbury exceeded expectations — the garden square view and the quiet street made it feel like a real escape in central London.', '2026-02-25 09:45:00', true, 5, 5, 7);
