-- DEMO CATALOGUE: 4 companies, 44 hotels/apartments in 10 cities, rooms, amenities,
-- description translations, and a handful of completed stays with reviews.
--
-- This is a Flyway "afterMigrate" callback, not a migration: it runs after every
-- migrate, but the guard below makes it insert only into an empty database, so it is
-- safe to run on each startup and never touches a database that already has hotels.
--
-- Loaded only when db/seed is in spring.flyway.locations: always in the "local" profile
-- (application-local.yml); for a public demo deployment set
-- SPRING_FLYWAY_LOCATIONS=classpath:db/migration,classpath:db/seed. Production and the
-- integration tests use db/migration only and start empty.
--
-- The review authors below are placeholder identities: their password hashes are not
-- real credentials and they can never sign in.

DO $seed$
BEGIN
    IF EXISTS (SELECT 1 FROM hotels) THEN
        RETURN;
    END IF;

    -- companies (4 rows)

    -- hotels (44 rows)

    -- hotel_amenities (246 rows)

    -- hotel_translations (220 rows)

    -- rooms (81 rows)

    -- users (5 rows)

    -- bookings (5 rows)

    -- reviews (5 rows)

    -- Rows were inserted with explicit ids: move each identity past them.
    PERFORM setval(pg_get_serial_sequence('companies', 'id'), (SELECT max(id) FROM companies));
    PERFORM setval(pg_get_serial_sequence('hotels', 'id'), (SELECT max(id) FROM hotels));
    PERFORM setval(pg_get_serial_sequence('hotel_translations', 'id'), (SELECT max(id) FROM hotel_translations));
    PERFORM setval(pg_get_serial_sequence('rooms', 'id'), (SELECT max(id) FROM rooms));
    PERFORM setval(pg_get_serial_sequence('users', 'id'), (SELECT max(id) FROM users));
    PERFORM setval(pg_get_serial_sequence('bookings', 'id'), (SELECT max(id) FROM bookings));
    PERFORM setval(pg_get_serial_sequence('reviews', 'id'), (SELECT max(id) FROM reviews));
END
$seed$;
